import re,subprocess
def rows(txt):
    d={}; order=[]
    for l in txt.splitlines():
        m=re.match(r'^\|\s*(\d+)\s*\|',l)
        if m: d[int(m.group(1))]=l; order.append(int(m.group(1)))
    return d,order
